insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_aspect','aspect','noun','one part or feature of a situation, problem or subject','[{"senseId":"aspect_1","meaning":"one part or feature of a situation, problem or subject","acceptedParaphrases":["feature","part"],"masteryContexts":[{"contextId":"u10_21_aspect_meaning","text":"The article looks at every aspect of school life, from lessons to lunches.","meaning":"one part or feature of something","wrongMeanings":["the total cost of something","the person in charge of something","the history of something"]},{"contextId":"u10_21_aspect_paraphrase","text":"For many students, the social aspect of university is as important as the studying.","meaning":"a particular side of a situation","wrongMeanings":["the cost of something","the place where something happens","the length of something"]}],"situationDistractors":["A student found out her final grade at the end of the course.","A careers adviser helped a boy choose a college.","The teacher said the essay must be handed in by Friday.","A student received his final mark.","A teacher gave advice about careers.","The deadline for the project was set for Monday."],"gapDistractors":[{"contextId":"u10_21_aspect_gap_1","answer":"aspect","wrong":["opportunity","achievement","interview"]},{"contextId":"u10_21_aspect_gap_2","answer":"aspect","wrong":["loneliness","literacy","recreation"]},{"contextId":"u10_21_aspect_gap_3","answer":"aspect","wrong":["loneliness","literacy","recreation"]}],"spellingErrors":["aspekt","aspact","asspect","aspec","apsect","aspeckt"],"masteryPassages":[{"passageId":"u10_21_aspect_passage_1","contextId":"u10_21_aspect_gap_1","text":"There are many good things about my new school. The most enjoyable ____ for me is the wide choice of clubs.","answer":"aspect"},{"passageId":"u10_21_aspect_passage_2","contextId":"u10_21_aspect_gap_2","text":"The report covers the cost of the plan and its effect on the environment. It does not consider the social ____ at all.","answer":"aspect"}],"contextDependentParaphrases":[],"wrongParaphrases":["result","adviser","deadline"],"misleadingDistractors":["the final result of a long process","a person who gives advice","the date when something must be finished"],"teacherNote":"Noun: one part or feature of something (an important aspect of, every aspect of, the social aspect). Countable. Common in Paper 2 writing: \"One positive aspect of ... is ...\". Boundary: an aspect is one feature among several; a factor is something that causes a result."}]'::jsonb,'[]'::jsonb,'["an important aspect of","every aspect of","the social aspect"]'::jsonb,'live'),
('vocab_industry','industry','noun','the businesses that produce a particular type of goods or provide a particular service','[{"senseId":"industry_1","meaning":"the businesses that produce a particular type of goods or provide a particular service","acceptedParaphrases":["business sector","type of business"],"masteryContexts":[{"contextId":"u10_22_industry_meaning","text":"She wants to work in the fashion industry as a designer.","meaning":"the businesses involved in one type of work","wrongMeanings":["a single shop that sells clothes","a school that teaches design","a magazine about style"]},{"contextId":"u10_22_industry_paraphrase","text":"The town grew quickly in the nineteenth century because of its steel industry.","meaning":"the production of goods in factories","wrongMeanings":["the farming of animals and crops","the building of new roads","the selling of goods in markets"]}],"situationDistractors":["A couple opened one small bakery in their village.","Parliament passed a new law about school uniforms.","A student moved into a shared flat near the university.","A boy opened a lemonade stand outside his house.","A girl sold her old bike to a neighbour.","A family grew vegetables just for themselves."],"gapDistractors":[{"contextId":"u10_22_industry_gap_1","answer":"industry","wrong":["loneliness","literacy","intonation"]},{"contextId":"u10_22_industry_gap_2","answer":"industry","wrong":["loneliness","literacy","pronunciation"]},{"contextId":"u10_22_industry_gap_3","answer":"industry","wrong":["loneliness","literacy","intonation"]}],"spellingErrors":["industy","indusrty","industri","indastry","industrey","inndustry"],"wordFamilyForms":[{"form":"industry","partOfSpeech":"noun","example":"The film industry employs many young people.","pedagogicallyUseful":true},{"form":"industrial","partOfSpeech":"adjective","example":"The town has a large industrial area near the river.","pedagogicallyUseful":true,"altExample":"The river was polluted by industrial waste."},{"form":"industrialise","partOfSpeech":"verb","example":"The country began to industrialise in the nineteenth century.","pedagogicallyUseful":true,"altExample":"Some countries tried to industrialise too quickly."}],"masteryPassages":[{"passageId":"u10_22_industry_passage_1","contextId":"u10_22_industry_gap_1","text":"Thousands of tourists visit the island every summer. Hotels, restaurants and tour guides depend on the tourism ____.","answer":"industry"},{"passageId":"u10_22_industry_passage_2","contextId":"u10_22_industry_gap_2","text":"The town grew rich because of its coal mines and steel works. When heavy ____ declined, many people left.","answer":"industry"}],"contextDependentParaphrases":[],"wrongParaphrases":["single shop","government law","student flat"],"misleadingDistractors":["a single shop owned by a family","a law passed by the government","a place where students live at university"],"teacherNote":"Noun: (1) the businesses in one area of trade (the film industry, the tourism industry); (2) the production of goods in factories in general (heavy industry). Countable in sense 1. The adjective industrial and the verb industrialise are taught in the Word Family pathway."}]'::jsonb,'["industrial","industrialise"]'::jsonb,'["the tourism industry","the music industry","work in industry"]'::jsonb,'live'),
('vocab_interview','interview','noun','a formal meeting in which someone is asked questions, for example to decide whether they are suitable for a job or course','[{"senseId":"interview_1","meaning":"a formal meeting in which someone is asked questions, for example to decide whether they are suitable for a job or course","acceptedParaphrases":["formal meeting with questions","question-and-answer session"],"masteryContexts":[{"contextId":"u10_23_interview_meaning","text":"Universities sometimes hold an interview before offering a student a place.","meaning":"a meeting to decide if someone is suitable","wrongMeanings":["a written exam taken by all applicants","a party for new students","a tour of the university buildings"]},{"contextId":"u10_23_interview_paraphrase","text":"The magazine published an interview with the famous singer.","meaning":"a conversation in which a journalist asks a person questions","wrongMeanings":["a song recorded by the singer","an advert paid for by the singer","a photo taken of the singer"]}],"situationDistractors":["Students sat a two-hour written exam in silence.","Friends held a party to celebrate Tom’s new job.","A student worked alone on a crossword in the library.","A student did a crossword alone.","A girl read a book in the library.","A class sat a silent multiple-choice test."],"gapDistractors":[{"contextId":"u10_23_interview_gap_1","answer":"interview","wrong":["literacy","loneliness","recreation"]},{"contextId":"u10_23_interview_gap_2","answer":"interview","wrong":["literacy","loneliness","recreation"]},{"contextId":"u10_23_interview_gap_3","answer":"interview","wrong":["literacy","loneliness","recreation"]}],"spellingErrors":["intervew","interveiw","intreview","intervue","interviw","intarview"],"masteryPassages":[{"passageId":"u10_23_interview_passage_1","contextId":"u10_23_interview_gap_1","text":"Kai applied for a part-time job at the sports centre. The manager invited him for an ____ next Tuesday.","answer":"interview"},{"passageId":"u10_23_interview_passage_2","contextId":"u10_23_interview_gap_2","text":"The famous footballer rarely speaks to journalists. However, he gave a long ____ to a newspaper after the final.","answer":"interview"}],"contextDependentParaphrases":[],"wrongParaphrases":["written exam","farewell party","silent reading session"],"misleadingDistractors":["a written test taken at the end of a course","a party to celebrate a new job","a lesson in which students work alone"],"teacherNote":"Noun: a formal meeting where someone is asked questions (a job interview, an interview for a place at university, give / have an interview); also a conversation with a famous person reported in the media. Also a verb (interview someone). The nouns interviewer and interviewee are taught in the Word Family pathway."}]'::jsonb,'[]'::jsonb,'["a job interview","have an interview","an interview for"]'::jsonb,'live'),
('vocab_overseas','overseas','adjective','from, in or connected with a foreign country, especially one across the sea','[{"senseId":"overseas_1","meaning":"from, in or connected with a foreign country, especially one across the sea","acceptedParaphrases":["foreign","from abroad"],"masteryContexts":[{"contextId":"u10_24_overseas_meaning","text":"Many overseas students need help finding accommodation when they first arrive.","meaning":"from another country","wrongMeanings":["from the same town","from a rich family","from the countryside"]},{"contextId":"u10_24_overseas_paraphrase","text":"The school organises an overseas trip every summer, usually to France or Spain.","meaning":"to or in a foreign country","wrongMeanings":["inside the local area","for younger students only","with no cost"]}],"situationDistractors":["A boy walked to the corner shop in his own street.","A girl visited her grandparents in the next village.","A student joined the local football club in his town.","A boy cycled to his friend’s house.","A family spent the weekend in their own city.","A student went to the local library."],"gapDistractors":[{"contextId":"u10_24_overseas_gap_1","answer":"overseas","wrong":["reluctant","academic","lonely"]},{"contextId":"u10_24_overseas_gap_2","answer":"overseas","wrong":["reluctant","academic","lonely"]},{"contextId":"u10_24_overseas_gap_3","answer":"overseas","wrong":["reluctant","lonely","accurate"]}],"spellingErrors":["oversease","overseeas","oversaes","ovverseas","overseaz","oveerseas"],"masteryPassages":[{"passageId":"u10_24_overseas_passage_1","contextId":"u10_24_overseas_gap_1","text":"Students come to the university from more than sixty countries. The ____ students often organise a festival of food from home.","answer":"overseas"},{"passageId":"u10_24_overseas_passage_2","contextId":"u10_24_overseas_gap_2","text":"Most of the company’s customers live abroad. In fact, ____ sales are now twice as high as local sales.","answer":"overseas"}],"contextDependentParaphrases":[],"wrongParaphrases":["local","rural","nearby"],"misleadingDistractors":["living in the same town","connected with the countryside","belonging to the local area"],"teacherNote":"Adjective: from or in a foreign country (overseas students, an overseas trip, overseas aid). Also an adverb (study overseas, work overseas). Same form in both uses; there is no \"overseasly\". Boundary: overseas usually suggests a distant country, often across the sea; abroad is the more general adverb."}]'::jsonb,'[]'::jsonb,'["overseas students","an overseas trip","study overseas"]'::jsonb,'live'),
('vocab_reluctant','reluctant','adjective','not wanting to do something and therefore slow to do it','[{"senseId":"reluctant_1","meaning":"not wanting to do something and therefore slow to do it","acceptedParaphrases":["unwilling","not keen"],"masteryContexts":[{"contextId":"u10_25_reluctant_meaning","text":"She was reluctant to leave her friends and move to a new city.","meaning":"not wanting to do something","wrongMeanings":["very excited about doing something","too tired to do something","proud of doing something"]},{"contextId":"u10_25_reluctant_paraphrase","text":"The reluctant students finally agreed to join the drama club.","meaning":"unwilling at first","wrongMeanings":["keen from the very start","unable to attend","already experienced"]}],"situationDistractors":["A boy jumped up immediately to volunteer for the school play.","A girl ran to the front of the queue to get her ticket.","A student proudly showed everyone his trophy.","A girl rushed to sign up for the trip.","A boy happily offered to help his teacher.","A student eagerly answered every question."],"gapDistractors":[{"contextId":"u10_25_reluctant_gap_1","answer":"reluctant","wrong":["academic","overseas","cosmopolitan"]},{"contextId":"u10_25_reluctant_gap_2","answer":"reluctant","wrong":["academic","overseas","cosmopolitan"]},{"contextId":"u10_25_reluctant_gap_3","answer":"reluctant","wrong":["academic","overseas","cosmopolitan"]}],"spellingErrors":["reluctent","relucant","reluctunt","relluctant","reluctannt","reluktant"],"wordFamilyForms":[{"form":"reluctant","partOfSpeech":"adjective","example":"He was reluctant to speak in front of the class.","pedagogicallyUseful":true},{"form":"reluctance","partOfSpeech":"noun","example":"Her reluctance to ask for help surprised her teacher.","pedagogicallyUseful":true,"altExample":"Despite his reluctance, he agreed to give the speech."},{"form":"reluctantly","partOfSpeech":"adverb","example":"He reluctantly agreed to sing at the concert.","pedagogicallyUseful":true,"altExample":"She reluctantly turned off her phone and opened her book."}],"masteryPassages":[{"passageId":"u10_25_reluctant_passage_1","contextId":"u10_25_reluctant_gap_1","text":"Omar did not want to join the debate because he hated speaking in public. His teacher understood why he was so ____.","answer":"reluctant"},{"passageId":"u10_25_reluctant_passage_2","contextId":"u10_25_reluctant_gap_2","text":"Most of the class were happy to try the new app. Only a few students were ____ to change the way they studied.","answer":"reluctant"}],"contextDependentParaphrases":[],"wrongParaphrases":["eager","exhausted","proud"],"misleadingDistractors":["excited and eager to start","too tired to continue","proud of what you have done"],"teacherNote":"Adjective: not wanting to do something (reluctant to do something, a reluctant student). Pattern: be reluctant + to-infinitive. The noun reluctance and the adverb reluctantly are taught in the Word Family pathway. Boundary: reluctant means unwilling but may still do it; refuse means will not do it at all."}]'::jsonb,'["reluctance","reluctantly"]'::jsonb,'["reluctant to","a reluctant student","slightly reluctant"]'::jsonb,'live'),
('vocab_cosmopolitan','cosmopolitan','adjective','having people, ideas or influences from many different countries and cultures','[{"senseId":"cosmopolitan_1","meaning":"having people, ideas or influences from many different countries and cultures","acceptedParaphrases":["multicultural","international"],"masteryContexts":[{"contextId":"u10_26_cosmopolitan_meaning","text":"Dubai has become a cosmopolitan city, with workers from all over the world.","meaning":"full of people from many countries","wrongMeanings":["quiet and far from other places","very expensive to live in","old and full of history"]},{"contextId":"u10_26_cosmopolitan_paraphrase","text":"After living in six countries, she has a very cosmopolitan outlook.","meaning":"showing experience of many cultures","wrongMeanings":["showing interest in only one culture","showing fear of travel","showing a love of money"]}],"situationDistractors":["A tiny farming village had only one road and one shop.","A family followed the same traditions for two hundred years.","A small mountain town had no visitors in winter.","A village had only twenty houses and one church.","A remote island had no visitors for months.","A small town had shops run by the same families for centuries."],"gapDistractors":[{"contextId":"u10_26_cosmopolitan_gap_1","answer":"cosmopolitan","wrong":["reluctant","academic","lonely"]},{"contextId":"u10_26_cosmopolitan_gap_2","answer":"cosmopolitan","wrong":["reluctant","lonely","accurate"]},{"contextId":"u10_26_cosmopolitan_gap_3","answer":"cosmopolitan","wrong":["reluctant","lonely","accurate"]}],"spellingErrors":["cosmopoliton","cosmopolitian","cosmapolitan","cosmopoliten","cosmoplitan","cossmopolitan"],"masteryPassages":[{"passageId":"u10_26_cosmopolitan_passage_1","contextId":"u10_26_cosmopolitan_gap_1","text":"On one street you can eat Thai, Lebanese and Mexican food. People from all over the world live here, making it a truly ____ city.","answer":"cosmopolitan"},{"passageId":"u10_26_cosmopolitan_passage_2","contextId":"u10_26_cosmopolitan_gap_2","text":"Students at the international school speak more than forty languages. The atmosphere is relaxed and very ____.","answer":"cosmopolitan"}],"contextDependentParaphrases":[],"wrongParaphrases":["isolated","old-fashioned","expensive"],"misleadingDistractors":["quiet and far from other towns","old-fashioned and traditional","small and very expensive"],"teacherNote":"Adjective: containing people and influences from many countries (a cosmopolitan city, a cosmopolitan atmosphere); of a person, having experience of many countries. Usually positive. Boundary: cosmopolitan describes a mix of cultures; international describes something involving more than one country."}]'::jsonb,'[]'::jsonb,'["a cosmopolitan city","a cosmopolitan atmosphere","truly cosmopolitan"]'::jsonb,'live'),
('vocab_assignment_10','assignment','noun','a piece of work that a student is given to do as part of a course','[{"senseId":"assignment_10_1","meaning":"a piece of work that a student is given to do as part of a course","acceptedParaphrases":["a piece of coursework","a task set by a teacher"],"masteryContexts":[{"contextId":"u10_27_assignment_10_meaning","text":"Our English assignment is to write a review of a book we have read.","meaning":"a piece of work set as part of a course","wrongMeanings":["a test given without warning","a book chosen for fun","a meeting with the head teacher"]},{"contextId":"u10_27_assignment_10_paraphrase","text":"At university, each long written assignment counts towards your final grade.","meaning":"a written task that counts towards a course","wrongMeanings":["a lecture given by a professor","a party for new students","a holiday between terms"]}],"situationDistractors":["The class was surprised by a quiz at the start of the lesson.","Students went home for a two-week holiday.","Parents met teachers in the hall to talk about progress.","A class watched a film for fun on the last day.","Students chatted in the canteen.","A teacher took the register."],"gapDistractors":[{"contextId":"u10_27_assignment_10_gap_1","answer":"assignment","wrong":["loneliness","literacy","recreation"]},{"contextId":"u10_27_assignment_10_gap_2","answer":"assignment","wrong":["loneliness","literacy","intonation"]},{"contextId":"u10_27_assignment_10_gap_3","answer":"assignment","wrong":["loneliness","literacy","recreation"]}],"spellingErrors":["assigment","asignment","assignmant","assinement","assignmint","asignmant"],"masteryPassages":[{"passageId":"u10_27_assignment_10_passage_1","contextId":"u10_27_assignment_10_gap_1","text":"Our history teacher has asked us to write a report on the causes of the war. The ____ must be handed in before the holidays.","answer":"assignment"},{"passageId":"u10_27_assignment_10_passage_2","contextId":"u10_27_assignment_10_gap_2","text":"University students often have several deadlines in the same week. Planning time for each ____ is an important skill.","answer":"assignment"}],"contextDependentParaphrases":[],"wrongParaphrases":["a surprise quiz","a school holiday","a parents’ meeting"],"misleadingDistractors":["a test that students take without warning","a holiday at the end of term","a meeting between parents and teachers"],"teacherNote":"Noun: a piece of work given to a student (a written assignment, hand in an assignment, set an assignment). Countable. Unit 10 uses it for school and university work; Unit 8 taught it for tasks at work. The verb assign is taught in the Word Family pathway."}]'::jsonb,'[]'::jsonb,'["a written assignment","hand in an assignment","set an assignment"]'::jsonb,'live'),
('vocab_loneliness','loneliness','noun','the unhappy feeling of being alone or having no friends to talk to','[{"senseId":"loneliness_1","meaning":"the unhappy feeling of being alone or having no friends to talk to","acceptedParaphrases":["isolation","the feeling of being alone"],"masteryContexts":[{"contextId":"u10_28_loneliness_meaning","text":"After his wife died, the old man struggled with loneliness.","meaning":"unhappiness from being alone","wrongMeanings":["anger at other people","excitement about the future","tiredness after hard work"]},{"contextId":"u10_28_loneliness_paraphrase","text":"Video calls with her family helped reduce her loneliness while she studied abroad.","meaning":"the feeling of missing people and being alone","wrongMeanings":["the cost of living in another country","the difficulty of a new language","the pleasure of being independent"]}],"situationDistractors":["A busy student had five tests and two clubs in one week.","A girl laughed with her friends at a birthday party.","A boy worried that he might fail his maths exam.","A boy chatted happily with a group of friends.","A girl was surrounded by her family at dinner.","A student enjoyed a busy party."],"gapDistractors":[{"contextId":"u10_28_loneliness_gap_1","answer":"loneliness","wrong":["qualification","industry","pronunciation"]},{"contextId":"u10_28_loneliness_gap_2","answer":"loneliness","wrong":["qualification","pronunciation","industry"]},{"contextId":"u10_28_loneliness_gap_3","answer":"loneliness","wrong":["qualification","industry","intonation"]}],"spellingErrors":["lonelyness","loneliess","lonliness","loneleness","lonelinness","loneliniss"],"masteryPassages":[{"passageId":"u10_28_loneliness_passage_1","contextId":"u10_28_loneliness_gap_1","text":"Chen moved abroad to study and did not know anyone. In the first few weeks, he suffered from terrible ____.","answer":"loneliness"},{"passageId":"u10_28_loneliness_passage_2","contextId":"u10_28_loneliness_gap_2","text":"Many elderly people live alone and rarely see anyone. Volunteers visit them every week to help reduce their ____.","answer":"loneliness"}],"contextDependentParaphrases":[],"wrongParaphrases":["busyness","happiness","nervousness"],"misleadingDistractors":["the feeling of being very busy","the pleasure of being with friends","the worry of failing an exam"],"teacherNote":"Noun: the unhappy feeling of being alone (feelings of loneliness, suffer from loneliness). Uncountable. Boundary: loneliness is unhappy; solitude is being alone by choice and can be positive. The adjective lonely is taught in the Word Family pathway; note \"lonely\" is an adjective, not an adverb."}]'::jsonb,'[]'::jsonb,'["feelings of loneliness","suffer from loneliness","reduce loneliness"]'::jsonb,'live'),
('vocab_opportunity','opportunity','noun','a time or situation when it is possible to do something you want to do','[{"senseId":"opportunity_1","meaning":"a time or situation when it is possible to do something you want to do","acceptedParaphrases":["chance","good moment"],"masteryContexts":[{"contextId":"u10_29_opportunity_meaning","text":"The summer job is an excellent opportunity to gain experience.","meaning":"a chance to do something useful","wrongMeanings":["a problem that cannot be solved","a rule that must be obeyed","a payment that must be made"]},{"contextId":"u10_29_opportunity_paraphrase","text":"Every child should have an equal opportunity to go to school, whatever their background.","meaning":"a fair chance that is open to everyone","wrongMeanings":["a rule that everyone must follow","a cost that everyone must pay","a test that everyone must pass"]}],"situationDistractors":["A broken leg stopped a boy from playing in the final.","Students had to wear school uniform every day.","A girl sent an email to the wrong person and could not get it back.","A girl missed the bus and had to walk.","A boy was told he could not join the team.","A student lost his ticket to the concert."],"gapDistractors":[{"contextId":"u10_29_opportunity_gap_1","answer":"opportunity","wrong":["loneliness","literacy","recreation"]},{"contextId":"u10_29_opportunity_gap_2","answer":"opportunity","wrong":["loneliness","literacy","recreation"]},{"contextId":"u10_29_opportunity_gap_3","answer":"opportunity","wrong":["loneliness","literacy","intonation"]}],"spellingErrors":["oppertunity","oportunity","opportunaty","opportunitey","oppotunity","opprtunity"],"masteryPassages":[{"passageId":"u10_29_opportunity_passage_1","contextId":"u10_29_opportunity_gap_1","text":"The exchange programme lets students live with a family in Spain. It is a wonderful ____ to improve their Spanish.","answer":"opportunity"},{"passageId":"u10_29_opportunity_passage_2","contextId":"u10_29_opportunity_gap_2","text":"Not every child in the world can go to school. Campaigners believe that every child deserves an equal ____ to learn.","answer":"opportunity"}],"contextDependentParaphrases":[],"wrongParaphrases":["obstacle","rule","mistake"],"misleadingDistractors":["a problem that stops you from acting","a rule that everyone must obey","a mistake that cannot be corrected"],"teacherNote":"Noun: a situation that makes it possible to do something (an opportunity to do something, take / miss an opportunity, job opportunities, equal opportunities). Countable. Boundary: opportunity is a good, often planned chance; chance can also mean luck or possibility."}]'::jsonb,'[]'::jsonb,'["an opportunity to","take the opportunity","equal opportunities"]'::jsonb,'live'),
('vocab_examination','examination','noun','a formal test of a student’s knowledge or ability in a subject','[{"senseId":"examination_1","meaning":"a formal test of a student’s knowledge or ability in a subject","acceptedParaphrases":["formal test","exam"],"masteryContexts":[{"contextId":"u10_30_examination_meaning","text":"Mobile phones are not allowed in the room during the examination.","meaning":"a formal test of knowledge","wrongMeanings":["an informal conversation","a lesson with a new teacher","a break between lessons"]},{"contextId":"u10_30_examination_paraphrase","text":"After the accident, the doctor carried out a full examination of the boy’s arm.","meaning":"a careful check of someone’s body","wrongMeanings":["an operation to fix the bone","a medicine to stop the pain","a bandage around the arm"]}],"situationDistractors":["A student had a relaxed chat with her teacher after class.","A boy bought a new revision guide in the bookshop.","The class went on a trip to the science museum.","A boy chatted with friends at lunch.","A girl browsed books in the library.","A class played a game in the playground."],"gapDistractors":[{"contextId":"u10_30_examination_gap_1","answer":"examination","wrong":["loneliness","recreation","literacy"]},{"contextId":"u10_30_examination_gap_2","answer":"examination","wrong":["loneliness","recreation","literacy"]},{"contextId":"u10_30_examination_gap_3","answer":"examination","wrong":["loneliness","recreation","literacy"]}],"spellingErrors":["examinasion","examanation","exammination","examinaton","exhamination","examinatoin"],"wordFamilyForms":[{"form":"examination","partOfSpeech":"noun","example":"The examination lasts two hours.","pedagogicallyUseful":true},{"form":"examine","partOfSpeech":"verb","example":"The doctor will examine your arm carefully.","pedagogicallyUseful":true,"altExample":"Scientists will examine the rocks brought back from Mars."},{"form":"examiner","partOfSpeech":"noun","example":"The examiner asked me to describe my hometown.","pedagogicallyUseful":true,"altExample":"Speak clearly so that the examiner can hear you."}],"masteryPassages":[{"passageId":"u10_30_examination_passage_1","contextId":"u10_30_examination_gap_1","text":"Students must arrive early and leave their phones in their bags. The ____ begins at nine o’clock and lasts two hours.","answer":"examination"},{"passageId":"u10_30_examination_passage_2","contextId":"u10_30_examination_gap_2","text":"After the fall, Tom’s arm was very painful. The doctor carried out a careful ____ before taking an X-ray.","answer":"examination"}],"contextDependentParaphrases":[],"wrongParaphrases":["informal chat","revision guide","school trip"],"misleadingDistractors":["an informal chat with a teacher","a book used for revision","a class trip to a museum"],"teacherNote":"Noun: a formal test of knowledge or ability (sit / take / pass / fail an examination); also a careful check (a medical examination). Countable. \"Exam\" is the common short form. The verb examine and the noun examiner are taught in the Word Family pathway."}]'::jsonb,'["examine","examiner"]'::jsonb,'["sit an examination","pass an examination","a final examination"]'::jsonb,'live')
